insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-1-check'), 'L1-1', 1, 'number', 'Hitung banyak kotak pada susunan ini.', '{"kind": "grid", "rows": 3, "cols": 3}'::jsonb, null, '{"value": 9}'::jsonb, 'Hitung banyak baris, lalu banyak kotak di setiap baris.', '["Susunan ini memiliki 3 baris.", "Setiap baris berisi 3 kotak.", "3 × 3 = 9. Jadi, ada 9 kotak."]'::jsonb, 'hubungan', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-1-check'), 'L1-2', 2, 'grid_choice', 'Manakah susunan yang membentuk persegi?', null, '[{"rows": 2, "cols": 3}, {"rows": 4, "cols": 4}, {"rows": 3, "cols": 5}, {"rows": 1, "cols": 4}]'::jsonb, '{"index": 1}'::jsonb, 'Persegi memiliki banyak baris yang SAMA dengan banyak kolom.', '["Susunan 2 × 3, 3 × 5, dan 1 × 4 memiliki baris dan kolom yang berbeda.", "Susunan 4 × 4 memiliki 4 baris dan 4 kolom.", "Jadi, susunan yang membentuk persegi adalah 4 × 4."]'::jsonb, 'identifikasi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-1-check'), 'L1-3', 3, 'tf', 'Bilangan 10 termasuk bilangan persegi.', null, null, '{"value": false}'::jsonb, 'Coba cari bilangan yang jika dikalikan dengan dirinya sendiri hasilnya 10.', '["3 × 3 = 9 dan 4 × 4 = 16.", "10 berada di antara 9 dan 16, jadi tidak ada bilangan asli yang dikalikan dirinya sendiri menghasilkan 10.", "Jadi, 10 BUKAN bilangan persegi. Pernyataan ini salah."]'::jsonb, 'alasan', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-2-check'), 'L2-1', 1, 'sequence', 'Lengkapi pola bilangan persegi berikut.', '{"kind": "sequence", "items": [1, 4, 9, 16, null]}'::jsonb, null, '{"values": [25]}'::jsonb, 'Lihat selisihnya: 3, 5, 7, ... selisih berikutnya bertambah 2.', '["Selisih antarsuku: 4 − 1 = 3, 9 − 4 = 5, 16 − 9 = 7.", "Selisih berikutnya adalah 7 + 2 = 9.", "16 + 9 = 25. Jadi, bilangan yang hilang adalah 25."]'::jsonb, 'strategi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-2-check'), 'L2-2', 2, 'mcq', 'Selisih antarsuku pada barisan 1, 4, 9, 16, 25 adalah ...', null, '["2, 3, 4, 5", "3, 5, 7, 9", "3, 4, 5, 6", "4, 5, 6, 7"]'::jsonb, '{"index": 1}'::jsonb, 'Kurangkan setiap suku dengan suku sebelumnya.', '["4 − 1 = 3", "9 − 4 = 5", "16 − 9 = 7", "25 − 16 = 9", "Jadi, selisihnya adalah 3, 5, 7, 9."]'::jsonb, 'hubungan', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-2-check'), 'L2-3', 3, 'number', 'Selisih antara 25 dan suku berikutnya adalah 11. Berapakah suku setelah 25?', null, null, '{"value": 36}'::jsonb, 'Suku berikutnya = 25 + selisihnya.', '["Diketahui suku sekarang 25 dan selisih berikutnya 11.", "25 + 11 = 36.", "Cek: 36 = 6 × 6, jadi benar termasuk bilangan persegi."]'::jsonb, 'strategi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-3-check'), 'L3-1', 1, 'number', 'Gunakan rumus Uₙ = n². Tentukan nilai U₇.', null, null, '{"value": 49}'::jsonb, 'U₇ artinya n = 7. Kalikan 7 dengan dirinya sendiri.', '["Diketahui n = 7.", "U₇ = 7² = 7 × 7.", "7 × 7 = 49. Jadi, U₇ = 49."]'::jsonb, 'konsep', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-3-check'), 'L3-2', 2, 'mcq', 'Pada rumus Uₙ = n², huruf n menyatakan ...', null, '["Nilai suku (banyak kotak)", "Nomor urutan suku (panjang sisi persegi)", "Selisih antarsuku", "Jumlah semua suku"]'::jsonb, '{"index": 1}'::jsonb, 'Ingat: n adalah nomor urutan suku, sama dengan panjang sisi perseginya.', '["Uₙ adalah NILAI suku ke-n (banyak kotak).", "n adalah NOMOR URUTAN suku.", "Pada susunan persegi, n juga sama dengan banyak kotak di setiap sisi."]'::jsonb, 'konsep', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-3-check'), 'L3-3', 3, 'number', 'Bilangan 64 merupakan suku ke berapa pada pola bilangan persegi?', null, null, '{"value": 8}'::jsonb, 'Cari bilangan yang jika dikalikan dengan dirinya sendiri hasilnya 64.', '["Kita mencari n sehingga n × n = 64.", "8 × 8 = 64.", "Jadi, 64 adalah suku ke-8 (n = 8)."]'::jsonb, 'strategi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-4-check'), 'L4-1', 1, 'number', 'Ubin kecil disusun membentuk persegi. Setiap sisi berisi 7 ubin. Berapa banyak ubin seluruhnya?', '{"kind": "grid", "rows": 7, "cols": 7}'::jsonb, null, '{"value": 49}'::jsonb, 'Susunan persegi dengan sisi 7 berarti 7 baris dan 7 kolom.', '["Diketahui: setiap sisi 7 ubin, jadi n = 7.", "Ditanya: banyak ubin seluruhnya.", "Jawab: 7 × 7 = 7² = 49.", "Jadi, diperlukan 49 ubin."]'::jsonb, 'identifikasi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-4-check'), 'L4-2', 2, 'number', 'Kursi di aula disusun membentuk persegi dan jumlahnya 100 kursi. Berapa kursi di setiap baris?', null, null, '{"value": 10}'::jsonb, 'Cari bilangan yang jika dikalikan dirinya sendiri hasilnya 100.', '["Diketahui: banyak kursi 100 dan susunannya persegi.", "Ditanya: banyak kursi di setiap baris (panjang sisi).", "Jawab: 10 × 10 = 100, jadi n = 10.", "Jadi, ada 10 kursi di setiap baris."]'::jsonb, 'strategi', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'lesson-4-check'), 'L4-3', 3, 'mcq', 'Tanaman di taman disusun: susunan ke-1 ada 1 tanaman, ke-2 ada 4, ke-3 ada 9. Rani berkata susunan ke-6 berisi 36 tanaman. Alasan yang paling tepat adalah ...', null, '["Karena setiap susunan selalu bertambah 6 tanaman", "Karena susunan ke-6 berbentuk persegi 6 × 6, sehingga 6² = 36", "Karena 36 adalah bilangan genap", "Karena 6 + 6 + 6 + 6 + 6 + 6 = 36 adalah kebetulan"]'::jsonb, '{"index": 1}'::jsonb, 'Pikirkan bentuk susunan ke-6: berapa tanaman di setiap sisinya?', '["Pola 1, 4, 9 adalah pola bilangan persegi.", "Susunan ke-6 berbentuk persegi 6 × 6.", "6² = 36, jadi alasan yang tepat adalah karena susunan ke-6 berbentuk persegi 6 × 6."]'::jsonb, 'alasan', true) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
