insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'training-beginner'), 'TB-12', 12, 'number', 'Perhatikan susunan ke-1, ke-2, dan ke-3. Berapa banyak kotak pada susunan ke-4?', '{"kind": "grid_series", "ns": [1, 2, 3]}'::jsonb, null, '{"value": 16}'::jsonb, 'Susunan ke-1 = 1 × 1, ke-2 = 2 × 2, ke-3 = 3 × 3. Bagaimana susunan ke-4?', '["Susunan ke-1 = 1 × 1 = 1, ke-2 = 2 × 2 = 4, ke-3 = 3 × 3 = 9.", "Susunan ke-4 berbentuk 4 × 4.", "4 × 4 = 16. Jadi, ada 16 kotak."]'::jsonb, 'hubungan', false) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
