insert into public.quiz_questions (quiz_id, code, position, type, prompt, visual, options, answer, hint, explanation, skill, ask_reason) values ((select id from public.quizzes where slug = 'training-expert'), 'TE-12', 12, 'number', 'Pak Budi menanam 81 pohon yang disusun membentuk persegi. Ia ingin memperbesar susunannya sehingga setiap sisi bertambah 1 pohon. Berapa pohon tambahan yang dibutuhkan?', null, null, '{"value": 19}'::jsonb, 'Cari dulu panjang sisi sekarang, lalu panjang sisi baru.', '["Diketahui: 81 pohon = 9 × 9, jadi sisi sekarang 9 pohon.", "Sisi baru = 9 + 1 = 10, banyak pohon = 10 × 10 = 100.", "Tambahan = 100 − 81 = 19.", "Jadi, dibutuhkan 19 pohon tambahan."]'::jsonb, 'tafsir', true) on conflict (code) do update set quiz_id = excluded.quiz_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, visual = excluded.visual, options = excluded.options, answer = excluded.answer, hint = excluded.hint, explanation = excluded.explanation, skill = excluded.skill, ask_reason = excluded.ask_reason;
